mapper.sql:
where w.plant_cd = #{plantCd}

   and w.status = #{status}
   and w.status in ('IN_PROGRESS', 'DONE')


  and (w.wo_no ilike '%' || #{keyword} || '%' escape '\' or i.item_cd ilike '%' || #{keyword} || '%' escape '\')

mapper.select:
select 

 order by w.plan_start desc, w.wo_id desc
 limit #{limit}
